const content=document.querySelector('#content');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>/^https?:\/\//i.test(s)?escapeHtml(s):'';
const art=p=>`<div class="art ${p.style}">${p.image?`<img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.title)} preview">`:'<div class="sculpture" aria-hidden="true"></div>'}<span class="art-label">${p.image?'':'PROJECT PREVIEW PLACEHOLDER'}</span><span class="arrow" aria-hidden="true">↗</span></div>`;
const head=(title,note)=>`<div class="section-head"><h2>${title}</h2><p>${note}</p></div>`;
function indicator(){let a=document.querySelector('.tabs .active');if(a){let i=document.querySelector('.tab-indicator');i.style.width=a.offsetWidth+'px';i.style.height=a.offsetHeight+'px';i.style.transform=`translateX(${a.offsetLeft-5}px)`;}}
function render(){let route=location.hash.slice(1)||'projects',detail=route.startsWith('project/'),tab=detail?'projects':route;if(!['projects','experience','skills','about'].includes(tab)){location.hash='projects';return;}document.querySelectorAll('[data-tab]').forEach(a=>{let on=a.dataset.tab===tab;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});indicator();let html='';
if(detail){let p=portfolio.projects.find(p=>p.id===route.split('/')[1]);if(!p){location.hash='projects';return;}html=`<article class="detail"><a class="back" href="#projects">← All projects</a><p class="eyebrow">${p.category} · PLACEHOLDER</p><h2>${escapeHtml(p.title)}</h2><p>${escapeHtml(p.description)}</p>${art(p)}<div class="detail-meta"><div><span class="date">ROLE</span><p>${escapeHtml(p.role)}</p></div><div><span class="date">TIMELINE</span><p>${escapeHtml(p.duration)}</p></div></div><div class="detail-copy">${[['Overview',p.overview],['The challenge',p.challenge],['The approach',p.approach],['Outcome & learnings',p.outcome]].map(([t,v])=>`<h3>${t}</h3><p>${escapeHtml(v)}</p>`).join('')}<div class="tags">${p.tags.map(t=>`<span class="tag">${escapeHtml(t)}</span>`).join('')}</div><p>${safeUrl(p.url)?`<a class="detail-link" href="${safeUrl(p.url)}" target="_blank" rel="noopener">View project ↗</a>`:'<span class="placeholder">Project link coming soon.</span>'} ${safeUrl(p.repo)?`<a class="detail-link" href="${safeUrl(p.repo)}" target="_blank" rel="noopener">Source code ↗</a>`:''}</p></div></article>`;}
else if(tab==='projects')html=head('Selected projects','A FEW THINGS I’VE WORKED ON')+`<div class="project-grid">${portfolio.projects.map(p=>`<a class="project-card" href="#project/${p.id}" aria-label="Read more about ${escapeHtml(p.title)}">${art(p)}<div class="card-meta"><span>${p.type}</span><span>${p.year}</span></div><h3>${p.title}</h3><p>${p.description}</p><div class="tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></a>`).join('')}</div>`;
else if(tab==='experience')html=head('Experience','MOST RECENT FIRST')+`<div class="timeline">${portfolio.experience.map(e=>`<article class="timeline-entry"><div><span class="date">${e.date}</span><h3>${e.role}</h3><div class="organization">${e.organization}</div>${e.description?`<p>${escapeHtml(e.description)}</p>`:''}</div>${e.image?`<div class="experience-logo ${e.logoClass||''}"><img src="${escapeHtml(e.image)}" alt="${escapeHtml(e.organization)}"></div>`:'<div class="image-placeholder">＋ Experience image</div>'}</article>`).join('')}</div>`;
else if(tab==='skills')html=head('My skills','ALWAYS ROOM TO LEARN')+`<div class="skills-grid">${portfolio.skills.map((s,i)=>s.certificate?`<button type="button" class="skill-card certificate-trigger" data-certificate="${i}" aria-label="View ${escapeHtml(s.name)} certificate"><img src="${s.image}" alt="" width="64" height="64"><h3>${escapeHtml(s.name)}</h3><span>View certificate ↗</span></button>`:`<div class="skill-card"><img src="${s.image}" alt="" width="64" height="64"><h3>${escapeHtml(s.name)}</h3></div>`).join('')}</div>`;
else html=head('A little more about me','BEYOND THE PROJECTS')+"<article class=\"about\"><p>I'm from Baltimore, MD. I’m interested in combining bioengineering and software to develop medical devices, healthcare technologies, and biotech solutions. In my free time, I enjoy watching sports, listening to music, and trying new foods.</p></article>";
content.innerHTML=`<section class="panel" aria-label="${detail?'Project details':tab}">${html}</section>`;document.title=(detail?'Project details':tab[0].toUpperCase()+tab.slice(1))+' — Elijah Higoy';}
let toastTimer;function toast(text){let t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('ehigoy@umd.edu');toast('Email copied to clipboard');}catch{let t=document.createElement('textarea');t.value='ehigoy@umd.edu';document.body.append(t);t.select();let ok=document.execCommand('copy');t.remove();toast(ok?'Email copied to clipboard':'Copy this email: ehigoy@umd.edu');}});
document.querySelectorAll('[data-social]').forEach(b=>{let url=safeUrl(portfolio[b.dataset.social.toLowerCase()]);if(url){let a=document.createElement('a');a.href=portfolio[b.dataset.social.toLowerCase()];a.className="social-link";a.append(...b.childNodes);a.target='_blank';a.rel='noopener';b.replaceWith(a);}else b.addEventListener('click',()=>toast(b.dataset.social+' link coming soon'));});
document.querySelector('#year').textContent=new Date().getFullYear();addEventListener('hashchange',render);addEventListener('resize',indicator);render();

const certificateDialog=document.createElement('dialog');
certificateDialog.className='certificate-dialog';
certificateDialog.setAttribute('aria-labelledby','certificate-title');
certificateDialog.innerHTML='<div class="certificate-header"><h2 id="certificate-title"></h2><button type="button" aria-label="Close certificate" autofocus>×</button></div><img class="certificate-image" alt="">';
document.body.append(certificateDialog);
content.addEventListener('click',event=>{
 const trigger=event.target.closest('[data-certificate]');if(!trigger)return;
 const skill=portfolio.skills[Number(trigger.dataset.certificate)];if(!skill?.certificate)return;
 certificateDialog.querySelector('h2').textContent=skill.name+' certificate';
 const img=certificateDialog.querySelector('img');img.src=skill.certificate;img.alt='Autodesk Certified User certificate in '+skill.name+' for Elijah Higoy';
 certificateDialog.showModal();document.body.style.overflow='hidden';
});
certificateDialog.querySelector('button').addEventListener('click',()=>certificateDialog.close());
certificateDialog.addEventListener('click',event=>{if(event.target===certificateDialog){const r=certificateDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)certificateDialog.close();}});
certificateDialog.addEventListener('close',()=>{document.body.style.overflow='';});
addEventListener('hashchange',()=>{if(certificateDialog.open)certificateDialog.close();});

const themeToggle=document.querySelector('#theme-toggle');
function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';themeToggle.setAttribute('aria-pressed',String(dark));themeToggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');themeToggle.title=themeToggle.getAttribute('aria-label');}
themeToggle.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('portfolio-theme',theme);}catch{}updateThemeButton();});updateThemeButton();
